CREATE TEMPORARY VIEW dwm_search_user_keyword_raw_${grass_region_without_quote} AS
SELECT
    local_date
    ,user_id
    ,device_id
    ,keyword
    ,page_type
    ,page_section
    ,target_type
    ,IF(is_ads IS NOT NULL, is_ads, 'false') AS is_ads
    ,IF(search_entrance IS NOT NULL AND trim(lower(search_entrance)) != '', trim(lower(search_entrance)), 'NA') AS search_entrance
    ,imp_cnt
    ,view_cnt
    ,ppv_cnt
    ,cart_cnt
    ,order_cnt
    ,gmv
    ,pc2_gmv
FROM
    srdi_mart.dws_sr_data_warehouse_search_srp_user_benchmark_1d
WHERE
    local_date IN (${local_date}, date_sub(${local_date}, 1), date_sub(${local_date}, 7))
    AND grass_region = ${grass_region}
    AND page_type IN ('global_search', 'search_in_pdp', 'search_prefill')
    AND user_id > 0;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_search_feature_${grass_region_without_quote} AS
SELECT
    user_id
    ,device_id
    ,keyword
    ,CASE
        WHEN page_section IS NULL AND target_type = 'item' THEN 'item'
        WHEN page_section IS NULL AND target_type = 'video' THEN 'video'
        WHEN page_section IS NULL AND target_type = 'livestream' THEN 'livestream'
        ELSE 'Other'
    END AS card_type
    ,cast(is_ads AS STRING) AS is_ads
    ,search_entrance
    ,IF(search_entrance IN ('live_search', 'video_search', 'content_mix_search'), 'all_content_search', 'not_content_search') AS is_content_entrance
    ,local_date
    ,SUM(imp_cnt) AS imp_cnt
    ,SUM(view_cnt) AS view_cnt
    ,SUM(order_cnt) AS order_cnt
    ,SUM(gmv) AS gmv
    ,SUM(pc2_gmv) AS pc2_gmv
    ,MAX(CASE WHEN view_cnt > 0 OR (imp_cnt > 0 AND target_type = 'no_recall_general') THEN true ELSE false END) AS keyword_flag
    ,MAX(CASE WHEN imp_cnt > 0 AND target_type = 'no_recall_general' THEN true ELSE false END) AS norecall_keyword_flag
FROM
    dwm_search_user_keyword_raw_${grass_region_without_quote} t1
GROUP BY
    1,2,3,4,5,6,7,8;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_entrance_${grass_region_without_quote} AS
SELECT
    user_id
    ,IF(GROUPING(card_type) = 1, '__ALL__', card_type) AS card_type
    ,IF(GROUPING(is_ads) = 1, '__ALL__', CAST(is_ads AS STRING)) AS is_ads
    ,search_entrance_exploded AS search_entrance
    ,SUM(if(card_type IN ('item', 'video', 'livestream') ,imp_cnt, 0)) AS imp_cnt
    ,SUM(if(card_type IN ('item', 'video', 'livestream') ,gmv, 0)) AS gmv
    ,SUM(if(card_type IN ('item', 'video', 'livestream') ,pc2_gmv, 0)) AS pc2_gmv
    ,CASE WHEN SUM(order_cnt) > 0 THEN SUM(gmv) / SUM(order_cnt) ELSE 0 END AS abs
FROM
    dws_search_feature_${grass_region_without_quote}
LATERAL VIEW
    EXPLODE(ARRAY(search_entrance, is_content_entrance, '__ALL__')) AS search_entrance_exploded
WHERE
    local_date = ${local_date}
    AND (
        card_type IN ('item', 'video', 'livestream')
        OR view_cnt > 0
    )
GROUP BY
    user_id, CUBE(card_type, is_ads), search_entrance_exploded;

--sql_divide_splitter--

CACHE TABLE global_search_abs995_benchmark_${grass_region_without_quote} AS
SELECT
    is_ads,
    APPROX_PERCENTILE(IF(abs > 0, abs, NULL), 0.995) AS global_search_abs_995 -- 每个地区每天，根据是否为广告会有三个阈值：广告、非广告、整体
FROM 
    dws_entrance_${grass_region_without_quote}
WHERE 
    search_entrance = '__ALL__'
    AND card_type = '__ALL__'
GROUP BY
    1;

--sql_divide_splitter--

CACHE TABLE dws_995_metrics_${grass_region_without_quote} AS
SELECT
/*+ BROADCASTJOIN(c) */
    exp_group_id
    ,card_type
    ,a.is_ads
    ,search_entrance
    ,SUM(IF(abs <= c.global_search_abs_995, gmv, 0)) AS gmv_995
    ,SUM(IF(abs <= c.global_search_abs_995, gmv, 0)) / COUNT(CASE WHEN imp_cnt > 0 AND abs <= c.global_search_abs_995 THEN a.user_id ELSE NULL END) AS gmv_uu_995
    ,SUM(IF(abs <= c.global_search_abs_995, pc2_gmv, 0)) AS pc2_gmv_995
    ,SUM(IF(abs <= c.global_search_abs_995, pc2_gmv, 0)) / COUNT(CASE WHEN imp_cnt > 0 AND abs <= c.global_search_abs_995 THEN a.user_id ELSE NULL END) AS pc2_gmv_uu_995
FROM
    dws_entrance_${grass_region_without_quote} a
INNER JOIN
    user_exp_mapping_1d_${grass_region_without_quote} b
ON
    a.user_id = b.user_id
LEFT JOIN
    global_search_abs995_benchmark_${grass_region_without_quote} c
ON
    a.is_ads = c.is_ads
GROUP BY
    1,2,3,4;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_norecall_rate_${grass_region_without_quote} AS
SELECT
    exp_group_id
    ,search_entrance_exploded AS search_entrance
    ,IF(
        COUNT(DISTINCT CASE WHEN keyword_flag = true THEN (a.user_id, a.keyword) ELSE NULL END) != 0
        ,1.0 * COUNT(DISTINCT CASE WHEN keyword_flag = true AND norecall_keyword_flag = true THEN (a.user_id, a.keyword) ELSE NULL END)
            / COUNT(DISTINCT CASE WHEN keyword_flag = true THEN (a.user_id, a.keyword) ELSE NULL END)
        ,0
    ) AS norecall_rate
FROM
    dws_search_feature_${grass_region_without_quote} a
JOIN
    user_exp_mapping_1d_${grass_region_without_quote} b
ON
    a.user_id = b.user_id
    AND a.local_date = b.local_date
LATERAL VIEW
    EXPLODE(ARRAY(search_entrance, is_content_entrance, '__ALL__')) AS search_entrance_exploded
GROUP BY
    1,2;

