-- live metrics --
CREATE TEMPORARY VIEW dwd_live_view_${grass_region_without_quote} AS
SELECT
    viewer_id as user_id
    ,view_event_id as event_id
    ,sum(duration_b * 1000) as duration_b
FROM 
    livestream.ls_mart_dwd_view_streaming_detail_di a
WHERE
    tz_type = 'local'
    AND a.grass_region = ${grass_region}
    AND a.grass_region IN ('ID', 'MY', 'PH', 'TH', 'TW', 'VN', 'SG')
    AND a.grass_date = ${local_date}
    AND viewer_id IS NOT NULL
    AND viewer_id > 0
GROUP BY
    1, 2;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dwd_live_duration_pv_${grass_region_without_quote} AS
SELECT
    a.user_id AS user_id
    ,IF(GET_JSON_OBJECT(data,'$.live_scene_parameters.live_in_search.search_entrance') IS NOT NULL AND TRIM(LOWER(GET_JSON_OBJECT(data,'$.live_scene_parameters.live_in_search.search_entrance'))) != '', TRIM(LOWER(GET_JSON_OBJECT(data,'$.live_scene_parameters.live_in_search.search_entrance'))), 'NA') AS search_entrance
    ,CASE
        WHEN GET_JSON_OBJECT(data, '$.from_source') = 'global_search_srp_live_card_entry' THEN 1
        WHEN GET_JSON_OBJECT(data, '$.from_source') IN (
            'global_search_live_floating_entry'
            ,'pdp_search_live_floating_entry'
            ,'prefill_search_live_floating_entry'
            ,'other_search_live_floating_entry'
            ,'search_shop_entry'
            ,'search_kol_avatar_entry'
            ,'search_sup_creator_avatar_entry'
            ,'search_creator_page_avatar_entry'
        ) THEN 2
        ELSE 3
    END AS source_type
    ,SUM(duration_b) AS duration  -- duration_b单位为秒
    ,COUNT(1) AS view_pv
FROM 
    livestream.ls_mart_dwd_viewer_view_detail_di a 
LEFT JOIN
    dwd_live_view_${grass_region_without_quote} b 
ON
    a.user_id = b.user_id
    AND a.event_id = b.event_id
WHERE 
    grass_date = ${local_date}
    AND grass_region = ${grass_region}
    AND grass_region IN ('ID', 'MY', 'PH', 'TH', 'TW', 'VN', 'SG')
    AND tz_type = 'local'
    AND a.user_id IS NOT NULL
    AND a.user_id > 0
GROUP BY 
    1,2,3;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dwd_live_order_${grass_region_without_quote} AS
SELECT
    order_buyer_id AS user_id
    ,COALESCE(GET_JSON_OBJECT(click_data,'$.live_scene_parameters.live_in_search.search_entrance'),'NA') AS search_entrance
    ,CASE WHEN GET_JSON_OBJECT(click_data, '$.ctx_from_source') = 'global_search_srp_live_card_entry' THEN 1
        WHEN GET_JSON_OBJECT(click_data, '$.ctx_from_source') IN (
            'global_search_live_floating_entry'
            ,'pdp_search_live_floating_entry'
            ,'prefill_search_live_floating_entry'
            ,'other_search_live_floating_entry'
            ,'search_shop_entry'
            ,'search_kol_avatar_entry'
            ,'search_sup_creator_avatar_entry'
            ,'search_creator_page_avatar_entry'
        ) THEN 2
        ELSE 3
    END AS source_type
    ,SUM(ls_order_fraction) as order
    ,SUM(gmv_usd) as gmv_usd
FROM
    mp_content_oa.dwd_ls_order_omni_local_content_final_detail_di
where
    grass_date = ${local_date}
    AND grass_region = ${grass_region}
    AND grass_region IN ('ID', 'MY', 'PH', 'TH', 'TW', 'VN', 'SG')
    AND tz_type = 'local'
    AND order_cal_type = 'direct'
    AND is_content_directly_related = 1
GROUP BY
    1,2,3;

