-- search session level metrics --
CREATE TEMPORARY VIEW dwd_search_session_${grass_region_without_quote} AS
SELECT
    user_id
    ,search_session_id
    ,IF(search_entrance IS NOT NULL AND trim(lower(search_entrance)) != '', trim(lower(search_entrance)), 'NA') AS search_entrance
    ,IF(search_entrance IN ('live_search', 'video_search', 'content_mix_search'), 'all_content_search', 'not_content_search') AS is_content_entrance
    ,first_click_location
    ,max_imp_location
    ,search_time
FROM srdi_mart.dws_sr_data_warehouse_search_session_level_metircs_1d
WHERE
    local_date = ${local_date}
    AND grass_region = ${grass_region}
    AND user_id > 0
    AND user_id IS NOT NULL;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dwd_first_location_${grass_region_without_quote} AS
SELECT
    user_id
    ,search_session_id
    ,first_click_location
    ,search_entrance
    ,is_content_entrance
    ,ROW_NUMBER() OVER(PARTITION BY user_id,search_session_id ORDER BY search_time ASC) AS click_time_rank
    ,ROW_NUMBER() OVER(PARTITION BY user_id,search_session_id,search_entrance ORDER BY search_time ASC) AS click_time_rank_tmp1
    ,ROW_NUMBER() OVER(PARTITION BY user_id,search_session_id,is_content_entrance ORDER BY search_time ASC) AS click_time_rank_tmp2
FROM
    dwd_search_session_${grass_region_without_quote}
WHERE
    first_click_location IS NOT NULL;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dwd_max_imp_location_${grass_region_without_quote} AS
SELECT
    user_id
    ,search_session_id
    ,search_entrance_exploded AS search_entrance
    ,MAX(max_imp_location) AS max_imp_location
FROM
    dwd_search_session_${grass_region_without_quote}
LATERAL VIEW
    EXPLODE(ARRAY(search_entrance, is_content_entrance, '__ALL__')) AS search_entrance_exploded
WHERE
    max_imp_location IS NOT NULL
GROUP BY
    1,2,3;

--sql_divide_splitter--

CACHE TABLE dws_first_location_${grass_region_without_quote} AS
SELECT
    exp_group_id
    ,'__ALL__' AS search_entrance
    ,AVG(first_click_location) as first_click_location_avg
    ,CASE
        WHEN COUNT(first_click_location) >= 1
        THEN ELEMENT_AT(SORT_ARRAY(COLLECT_LIST(first_click_location)), 1 + CAST(COUNT(first_click_location) / 2 AS INT))
        ELSE NULL
    END AS first_click_location_p50
FROM
    dwd_first_location_${grass_region_without_quote} a
JOIN
    user_exp_mapping_1d_${grass_region_without_quote} b
ON
    a.user_id = b.user_id
WHERE
    click_time_rank = 1
GROUP BY
    1,2
UNION ALL
SELECT
    exp_group_id
    ,search_entrance
    ,AVG(first_click_location) as first_click_location_avg
    ,CASE
        WHEN COUNT(first_click_location) >= 1
        THEN ELEMENT_AT(SORT_ARRAY(COLLECT_LIST(first_click_location)), 1 + CAST(COUNT(first_click_location) / 2 AS INT))
        ELSE NULL
    END AS first_click_location_p50
FROM
    dwd_first_location_${grass_region_without_quote} a
JOIN
    user_exp_mapping_1d_${grass_region_without_quote} b
ON
    a.user_id = b.user_id
WHERE
    click_time_rank_tmp1 = 1
GROUP BY
    1,2
UNION ALL
SELECT
    exp_group_id
    ,is_content_entrance AS search_entrance
    ,AVG(first_click_location) as first_click_location_avg
    ,CASE
        WHEN COUNT(first_click_location) >= 1
        THEN ELEMENT_AT(SORT_ARRAY(COLLECT_LIST(first_click_location)), 1 + CAST(COUNT(first_click_location) / 2 AS INT))
        ELSE NULL
    END AS first_click_location_p50
FROM
    dwd_first_location_${grass_region_without_quote} a
JOIN
    user_exp_mapping_1d_${grass_region_without_quote} b
ON
    a.user_id = b.user_id
WHERE
    click_time_rank_tmp2 = 1
GROUP BY
    1,2;

--sql_divide_splitter--

CACHE TABLE dws_max_imp_location_${grass_region_without_quote} AS
SELECT
    exp_group_id
    ,search_entrance 
    ,AVG(max_imp_location) AS max_imp_location_avg
    ,CASE
        WHEN count(max_imp_location) >= 1
        THEN ELEMENT_AT(SORT_ARRAY(COLLECT_LIST(max_imp_location)), 1 + CAST(COUNT(max_imp_location) / 2 AS INT))
        ELSE NULL
    END AS max_imp_location_p50
FROM
    dwd_max_imp_location_${grass_region_without_quote} a
JOIN
    user_exp_mapping_1d_${grass_region_without_quote} b
ON
    a.user_id = b.user_id
GROUP BY
    1,2;

