    AND feature_group = 'dpm module Global Search business line Search';

--sql_divide_splitter--

CREATE TEMPORARY VIEW gmv995_v2_item_order_grouped_${grass_region_without_quote} AS
SELECT
    user_id
    ,card_type_exploded AS card_type
    ,is_ads_exploded AS is_ads
    ,search_entrance_exploded AS search_entrance
    ,a.item_id AS item_id
    ,order_id
    ,COALESCE(category_tag, 'low gmv') AS category_tag
    ,COALESCE(SUM(order_cnt), 0.0) AS order_cnt
    ,COALESCE(SUM(gmv), 0.0) AS gmv
    ,COALESCE(SUM(pc2_gmv), 0.0) AS pc2_gmv
FROM
    gmv995_v2_metrics_raw_${grass_region_without_quote} a
LEFT JOIN
    srdi_mart.dim_sr_data_warehouse_item c
ON
    a.item_id = c.item_id
    AND c.local_date = ${local_date}
    AND c.grass_region = ${grass_region}
LATERAL VIEW
    EXPLODE(ARRAY(card_type, '__ALL__')) AS card_type_exploded
LATERAL VIEW
    EXPLODE(ARRAY(is_ads, '__ALL__')) AS is_ads_exploded
LATERAL VIEW
    EXPLODE(ARRAY(search_entrance, is_content_entrance, '__ALL__')) AS search_entrance_exploded
GROUP BY
    1,2,3,4,5,6,7;

--sql_divide_splitter--

CREATE TEMPORARY VIEW gmv995_v2_user_level_filtered_${grass_region_without_quote} AS
SELECT
/*+ BROADCASTJOIN(b) */
    user_id
    ,card_type
    ,a.is_ads AS is_ads
    ,search_entrance
    ,a.category_tag AS category_tag
    ,SUM(IF(gmv <= gmv_995pct, order_cnt, 0)) AS gmv_order_cnt_995_v2
    ,SUM(IF(gmv <= gmv_995pct, gmv, gmv_995pct)) AS gmv_995_v2
    ,SUM(IF(pc2_gmv <= pc2_gmv_995pct, pc2_gmv, pc2_gmv_995pct)) AS pc2_gmv_995_v2
FROM
    gmv995_v2_item_order_grouped_${grass_region_without_quote} a
LEFT JOIN
    gmv995_v2_outlier_${grass_region_without_quote} b
ON
    a.is_ads = b.is_ads
    AND a.category_tag = b.category_tag
GROUP BY
    1,2,3,4,5;

--sql_divide_splitter--

CREATE TEMPORARY VIEW gmv995_v2_metrics_${grass_region_without_quote} AS
SELECT
    exp_group_id
    ,card_type
    ,search_entrance
    ,is_ads
    ,SUM(IF(category_tag = 'high gmv', gmv_order_cnt_995_v2, NULL)) AS high_gmv_order_cnt_995_v2
    ,SUM(IF(category_tag = 'high gmv', gmv_995_v2, NULL)) AS high_gmv_995_v2
    ,SUM(IF(category_tag = 'high gmv', pc2_gmv_995_v2, NULL)) AS high_pc2_gmv_995_v2
    ,SUM(IF(category_tag = 'low gmv', gmv_order_cnt_995_v2, NULL)) AS low_gmv_order_cnt_995_v2
    ,SUM(IF(category_tag = 'low gmv', gmv_995_v2, NULL)) AS low_gmv_995_v2
    ,SUM(IF(category_tag = 'low gmv', pc2_gmv_995_v2, NULL)) AS low_pc2_gmv_995_v2
FROM
    gmv995_v2_user_level_filtered_${grass_region_without_quote} a
JOIN
    user_exp_mapping_1d_${grass_region_without_quote} b
ON
    a.user_id = b.user_id
GROUP BY
    1,2,3,4;

--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_search_abtest_entrance_card_type_other_metrics_1d
PARTITION (
    grass_region = ${grass_region}
    ,local_date = ${local_date}
)
SELECT
    scene_id
    ,scene_name
    ,layer_id
    ,layer_name
    ,experiment_id
    ,experiment_name
    ,a.exp_group_id
    ,exp_group_name
    ,a.is_ads
    ,a.card_type
    ,a.search_entrance
    ,ads_revenue
    ,search_uu_1d
    ,retention_uu_1d
    ,search_uu_7d
    ,retention_uu_7d
    ,CAST(srp_duration AS DOUBLE) / CAST(search_uu AS DOUBLE) AS srp_duration_per_uu
    ,CAST(pdp_duration AS DOUBLE) / CAST(search_uu AS DOUBLE) AS pdp_duration_per_uu
    ,CAST(video_duration AS DOUBLE) / CAST(search_uu AS DOUBLE) AS video_duration_per_uu
    ,CAST(search_to_live_duration_time AS DOUBLE) / CAST(search_uu AS DOUBLE) AS live_duration_per_uu

    ,search_scene_imp_cnt
    ,paidads_imp_cnt
    ,gmv_995
    ,gmv_uu_995
    ,pc2_gmv_995
    ,pc2_gmv_uu_995
    ,norecall_rate

    ,search_to_live_viewer
    ,search_to_live_view_pv
    ,search_to_live_duration_time
    ,search_to_live_order
    ,search_to_live_gmv
    ,all_live_side_viewer
    ,all_live_side_view_pv
    ,all_live_side_duration_time
    ,all_live_side_order
    ,all_live_side_gmv

    ,search_to_video_viewer
    ,search_to_video_vv
    ,search_to_video_duration_time
    ,search_to_video_order
    ,search_to_video_gmv
    ,all_video_side_viewer
    ,all_video_side_vv
    ,all_video_side_duration_time
    ,all_video_side_order
    ,all_video_side_gmv

    ,max_imp_location_avg
    ,max_imp_location_p50
    ,first_click_location_avg
    ,first_click_location_p50

    ,high_gmv_order_cnt_995_v2
    ,high_gmv_995_v2
    ,high_pc2_gmv_995_v2
    ,low_gmv_order_cnt_995_v2
    ,low_gmv_995_v2
    ,low_pc2_gmv_995_v2
FROM
    dws_995_metrics_${grass_region_without_quote} a
LEFT JOIN
    dim_exp_${grass_region_without_quote} b
ON
    a.exp_group_id = b.exp_group_id
LEFT JOIN
    retention_exp_${grass_region_without_quote} c
ON
    a.exp_group_id = c.exp_group_id
    AND a.search_entrance = c.search_entrance
    AND a.is_ads = '__ALL__'
    AND a.card_type = '__ALL__'
LEFT JOIN
    dws_ads_performance_${grass_region_without_quote} d
ON
    a.exp_group_id = d.exp_group_id
    AND a.search_entrance = d.search_entrance
    AND a.is_ads = '__ALL__'
    AND a.card_type = '__ALL__'
LEFT JOIN
    dws_video_duration_${grass_region_without_quote} e
ON
    a.exp_group_id = e.exp_group_id
    AND a.search_entrance = e.search_entrance
    AND a.is_ads = '__ALL__'
    AND a.card_type = e.card_type
LEFT JOIN
    dws_srp_duration_${grass_region_without_quote} f
ON
    a.exp_group_id = f.exp_group_id
    AND a.search_entrance = f.search_entrance
    AND a.is_ads = '__ALL__'
    AND a.card_type = '__ALL__'
LEFT JOIN
    dws_pdp_duration_${grass_region_without_quote} g
ON
    a.exp_group_id = g.exp_group_id
    AND a.search_entrance = g.search_entrance
    AND a.is_ads = '__ALL__'
    AND a.card_type = '__ALL__'
LEFT JOIN
    dws_live_duration_${grass_region_without_quote} h
ON
    a.exp_group_id = h.exp_group_id
    AND a.search_entrance = h.search_entrance
    AND a.is_ads = '__ALL__'
    AND a.card_type = h.card_type
LEFT JOIN
    search_scene_exp_${grass_region_without_quote} m 
ON
    a.exp_group_id = m.exp_group_id
    AND a.search_entrance = m.search_entrance
    AND a.is_ads = '__ALL__'
    AND a.card_type = '__ALL__'
LEFT JOIN
    dws_norecall_rate_${grass_region_without_quote} n
ON
    a.exp_group_id = n.exp_group_id
    AND a.search_entrance = n.search_entrance
    AND a.is_ads = '__ALL__'
    AND a.card_type = '__ALL__'
LEFT JOIN
    dws_video_metrics_${grass_region_without_quote} o
ON
    a.exp_group_id = o.exp_group_id
    AND a.search_entrance = '__ALL__'
    AND a.is_ads = '__ALL__'
    AND a.card_type = o.card_type
LEFT JOIN
    dws_live_order_${grass_region_without_quote} p
ON
    a.exp_group_id = p.exp_group_id
    AND a.search_entrance = p.search_entrance
    AND a.is_ads = '__ALL__'
    AND a.card_type = p.card_type
LEFT JOIN
    dws_first_location_${grass_region_without_quote} q
ON
    a.exp_group_id = q.exp_group_id
    AND a.search_entrance = q.search_entrance
    AND a.is_ads = '__ALL__'
    AND a.card_type = '__ALL__'
LEFT JOIN
    dws_max_imp_location_${grass_region_without_quote} r
ON
    a.exp_group_id = r.exp_group_id
    AND a.search_entrance = r.search_entrance
    AND a.is_ads = '__ALL__'
    AND a.card_type = '__ALL__'
LEFT JOIN
    gmv995_v2_metrics_${grass_region_without_quote} s
ON
    a.exp_group_id = s.exp_group_id
    AND a.search_entrance = s.search_entrance
    AND a.is_ads = s.is_ads
    AND a.card_type = s.card_type;
